def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    frame_color = 5

    # Find bounding box of frame_color (5)
    positions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == frame_color:
                positions.append((r, c))

    if not positions:
        return [[0]*w for _ in range(h)]

    top = min(r for r, c in positions)
    bottom = max(r for r, c in positions)
    left = min(c for r, c in positions)
    right = max(c for r, c in positions)

    out_h = bottom - top + 1
    out_w = right - left + 1

    # Verify frame completeness and extract interior
    # Count colors in potential interior region
    interior = []
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            if grid[r][c] != frame_color:
                interior.append(grid[r][c])

    # If there's interior content, use most common color as border
    if interior:
        counts = Counter(interior)
        border_color = max(counts.items(), key=lambda x: x[1])[0]
    else:
        border_color = frame_color

    # Build output grid
    output = [[0] * out_w for _ in range(out_h)]

    for r in range(out_h):
        for c in range(out_w):
            if r == 0 or r == out_h - 1 or c == 0 or c == out_w - 1:
                output[r][c] = border_color
            elif r < out_h and c < out_w:
                output[r][c] = grid[top + r][left + c]

    return output
